import {createRideController} from './winter-rides.js';
const copy={
 tree:['WINTER WISHES','가지마다 눈과 작은 불빛. 오늘은 어떤 순간을 오래 간직하고 싶나요?'],
 ski:['ALPINE CLUB','부츠와 스키를 착용하고 리프트에 올라요. 정상에 도착하면 슬로프를 내려갈 수 있어요.'],
 sled:['SNOW PLAY','작은 나무 썰매에 올라, 눈길을 따라 미끄러져요.'],
 onsen:['WARM WATER','차가운 공기, 따뜻한 물. 돌 가장자리에 앉아 잠깐 쉬어가요.'],
 sauna:['CEDAR ROOM','편백나무 벤치에 앉아 천천히 숨을 고르는 시간.'],
 classical:['PIANO SALON','작은 그랜드 피아노 곁에서 잔잔한 아르페지오를 들어요.'],
 gallery:['WINTER GALLERY','세 개의 작은 추상화. 같은 모양도 색과 배치에 따라 다르게 느껴져요.'],
 ethics:['THOUGHTFUL CORNER','법이 허용하는 것과 옳다고 생각하는 것은 언제 같고, 언제 다를까요?'],
 healing:['SLOW MOMENT','네 박자 들이쉬고, 여섯 박자 내쉬기. 편안한 속도로 쉬어가요.']};
export function createWinterExperience(winter,companion,travel){
 const rides=createRideController(winter.rides),card=document.querySelector('#place-card'),actions=document.querySelector('#place-actions'),hud=document.querySelector('#ride-hud'),label=document.querySelector('#ride-label');let place=null,rest=null,lastMode='',audio=null,musicTimer=null;
 function button(text,fn){const b=document.createElement('button');b.textContent=text;b.onclick=fn;actions.append(b);}
 function stop(){rides.stop();rest=null;companion.equip();winter.rideChair.visible=false;hud.hidden=true;travel(place?.id==='sled'?'sled':place?.id||'ski',false);}
 function start(kind){rest=null;if(rides.start(kind)){companion.equip(kind==='sled'?'sled':'ski');card.hidden=true;hud.hidden=false;lastMode='';}}
 function piano(){if(!musicTimer&&(document.querySelector('#sound').getAttribute('aria-checked')==='false'||!(window.AudioContext||window.webkitAudioContext))){document.querySelector('#place-description').textContent='소리 설정을 켜고 다시 눌러 주세요. 이 브라우저가 소리 재생을 지원해야 해요.';return;}if(musicTimer){clearInterval(musicTimer);musicTimer=null;audio?.close();audio=null;show(place.id);return;}audio=new(window.AudioContext||window.webkitAudioContext)();audio.resume();let beat=0;const notes=[60,64,67,72,67,64,57,60,64,69,64,60,53,57,60,65,60,57,55,59,62,67,62,59];const play=()=>{if(document.querySelector('#sound').getAttribute('aria-checked')==='false'){clearInterval(musicTimer);musicTimer=null;audio?.close();audio=null;return;}const volume=Number(document.querySelector('#sound-volume').value)/100;const freq=440*2**((notes[beat++%notes.length]-69)/12);for(const [ratio,gain]of [[1,.09],[2,.035],[3,.012]]){const osc=audio.createOscillator(),amp=audio.createGain();osc.frequency.value=freq*ratio;amp.gain.setValueAtTime(Math.max(.0001,gain*volume),audio.currentTime);amp.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+2);osc.connect(amp).connect(audio.destination);osc.start();osc.stop(audio.currentTime+2);}};play();musicTimer=setInterval(play,420);show(place.id);}
 function show(id){place=winter.destinations.find(p=>p.id===id);if(!place)return;const [kind,description]=copy[id];document.querySelector('#place-kind').textContent=kind;document.querySelector('#place-name').textContent=place.name;document.querySelector('#place-description').textContent=description;actions.replaceChildren();if(id==='ski'){button('부츠 신고 리프트 타기',()=>start('lift'));if(rides.mode==='summit')button('슬로프 내려가기',()=>start('ski'));}else if(id==='sled')button('썰매 타기',()=>start('sled'));else if(id==='classical')button(musicTimer?'피아노 멈추기':'피아노 듣기',piano);else if(['onsen','sauna','healing'].includes(id))button('잠깐 쉬기',()=>{rides.stop();companion.equip();const seats={onsen:{x:-12.9,y:1.18,z:56,yaw:Math.PI/2},sauna:{x:7.3,y:1.5,z:56,yaw:Math.PI/2},healing:{x:50,y:1,z:35.5,yaw:Math.PI}};rest=seats[id];card.hidden=true;hud.hidden=false;label.textContent=id==='healing'?'천천히 숨을 고르는 중':'따뜻하게 쉬는 중';});if(['ethics','gallery','classical','tree'].includes(id))button(id==='tree'?'작은 발견 펼치기':'생각 펼치기',()=>window.openWinterReading?.(id));card.hidden=false;}
 document.querySelector('#close-place').onclick=()=>card.hidden=true;document.querySelector('#stop-ride').onclick=stop;
 return{rides,show,cancel(){rides.stop();rest=null;companion.equip();winter.rideChair.visible=false;hud.hidden=true;card.hidden=true;},get active(){return!!rides.mode||!!rest;},update(dt){const result=rest?{...rest,mode:'rest'}:rides.update(dt);winter.rideChair.visible=rides.mode==='lift';if(winter.rideChair.visible&&result)winter.rideChair.position.set(result.x,result.y-.55,result.z);if(rides.mode!==lastMode){lastMode=rides.mode;if(lastMode==='summit'){show('ski');label.textContent='정상 도착 · 슬로프를 내려가 볼까요?';}else if(lastMode)label.textContent={lift:'리프트로 정상까지',ski:'눈 위를 가볍게',sled:'눈썰매 타는 중'}[lastMode];}if(result?.finished){companion.equip();hud.hidden=true;show(place.id);}return result;}};
}
